package alphametics

import (
	"fmt"
	"sort"
	"strings"
)

// Solve solves an alphametics puzzle of the form
// "TERM + TERM + ... == TERM" and returns the mapping from each letter to its
// digit. Each letter maps to a distinct digit, and the leading digit of any
// multi-digit term must not be zero. An error is returned when no valid
// assignment exists.
func Solve(puzzle string) (map[string]int, error) {
	eq := strings.Split(puzzle, "==")
	if len(eq) != 2 {
		return nil, fmt.Errorf("invalid puzzle %q: expected exactly one '=='", puzzle)
	}
	leftTerms := strings.Fields(eq[0])
	rightTerms := strings.Fields(eq[1])
	if len(leftTerms) == 0 || len(rightTerms) == 0 {
		return nil, fmt.Errorf("invalid puzzle %q: missing terms", puzzle)
	}

	// Build a linear constraint. Expanding each term as a number, the puzzle
	// reduces to: sum over letters of (coefficient[letter] * digit[letter]) == 0
	// where the coefficient accumulates 10^position for each occurrence of the
	// letter (positive on the left of '==', negative on the right).
	coeff := make(map[rune]int64)
	leading := make(map[rune]bool)

	addTerm := func(term string, sign int64) {
		rs := []rune(term)
		for i, r := range rs {
			coeff[r] += sign * pow10(len(rs)-1-i)
		}
		if len(rs) > 1 {
			leading[rs[0]] = true
		}
	}
	for _, t := range leftTerms {
		addTerm(t, 1)
	}
	for _, t := range rightTerms {
		addTerm(t, -1)
	}

	// Collect the distinct letters.
	letterSet := make(map[rune]bool, len(coeff))
	for r := range coeff {
		letterSet[r] = true
	}
	letters := make([]rune, 0, len(letterSet))
	for r := range letterSet {
		letters = append(letters, r)
	}
	if len(letters) > 10 {
		return nil, fmt.Errorf("puzzle has %d distinct letters; at most 10 can be assigned", len(letters))
	}

	// Assign the highest-impact letters first so the bound prunes earlier.
	sort.Slice(letters, func(i, j int) bool {
		return abs64(coeff[letters[i]]) > abs64(coeff[letters[j]])
	})

	n := len(letters)
	coefs := make([]int64, n)
	isLeading := make([]bool, n)
	for i, r := range letters {
		coefs[i] = coeff[r]
		isLeading[i] = leading[r]
	}

	assignment := make([]int, n)
	for i := range assignment {
		assignment[i] = -1
	}
	used := make([]bool, 10)
	best := make(map[string]int, n)

	var solve func(idx int, sum int64) bool
	solve = func(idx int, sum int64) bool {
		if idx == n {
			if sum == 0 {
				for i, r := range letters {
					best[string(r)] = assignment[i]
				}
				return true
			}
			return false
		}

		// Prune: the unassigned letters must be able to contribute exactly -sum.
		if !canReach(-sum, idx, coefs, used) {
			return false
		}

		for d := 0; d < 10; d++ {
			if used[d] {
				continue
			}
			if isLeading[idx] && d == 0 {
				continue
			}
			assignment[idx] = d
			used[d] = true
			if solve(idx+1, sum+coefs[idx]*int64(d)) {
				return true
			}
			used[d] = false
			assignment[idx] = -1
		}
		return false
	}

	if !solve(0, 0) {
		return nil, fmt.Errorf("no solution")
	}
	return best, nil
}

// canReach reports whether the not-yet-assigned letters (coefs[idx:]) can
// contribute a total of exactly `target`, each taking a distinct unused digit.
//
// It computes the exact maximum and minimum of the remaining dot product.
// Positive coefficients are paired with the largest available digits and
// negative coefficients with the smallest (the rearrangement inequality makes
// this the true extremum, and the two groups use disjoint digit sets). These
// bounds are then checked against `target`.
func canReach(target int64, idx int, coefs []int64, used []bool) bool {
	rem := coefs[idx:]
	if len(rem) == 0 {
		return target == 0
	}

	pool := make([]int64, 0, 10-idx)
	for d := 0; d < 10; d++ {
		if !used[d] {
			pool = append(pool, int64(d))
		}
	}
	asc := append([]int64(nil), pool...)
	sort.Slice(asc, func(i, j int) bool { return asc[i] < asc[j] })
	desc := append([]int64(nil), pool...)
	sort.Slice(desc, func(i, j int) bool { return desc[i] > desc[j] })

	var pos, neg []int64
	for _, c := range rem {
		switch {
		case c > 0:
			pos = append(pos, c)
		case c < 0:
			neg = append(neg, c)
		}
	}
	sort.Slice(pos, func(i, j int) bool { return pos[i] > pos[j] }) // most positive first
	sort.Slice(neg, func(i, j int) bool { return neg[i] < neg[j] }) // most negative first

	// Maximum: positive coeffs take the largest digits, negative the smallest.
	// Minimum: the reverse.
	var maxRem, minRem int64
	for j, c := range pos {
		maxRem += c * desc[j]
		minRem += c * asc[j]
	}
	for j, c := range neg {
		maxRem += c * asc[j]
		minRem += c * desc[j]
	}
	return target >= minRem && target <= maxRem
}

func pow10(n int) int64 {
	var r int64 = 1
	for i := 0; i < n; i++ {
		r *= 10
	}
	return r
}

func abs64(v int64) int64 {
	if v < 0 {
		return -v
	}
	return v
}

